#nullable enable

using System.Threading;
using Microsoft.CodeAnalysis;
using Microsoft.CodeAnalysis.CSharp.Syntax;
using Microsoft.CodeAnalysis.Operations;

namespace Haitch.Roslyn.Semantics;

/// <summary>
/// Reads an invocation's method and its arguments by the parameters they bind to, so a generator
/// does not walk <see cref="IInvocationOperation"/> or compare display strings by hand.
/// </summary>
internal static class InvocationExtensions
{
    /// <summary>
    /// Finds the value bound to <paramref name="parameter"/>, whether the caller wrote it
    /// positionally, by name in any order, or as an extension method's receiver; null when the
    /// argument is omitted or the call does not bind.
    /// </summary>
    /// <param name="invocation">The invocation to read.</param>
    /// <param name="model">The semantic model of the invocation's syntax tree.</param>
    /// <param name="parameter">The parameter name, including an extension method's <c>this</c> parameter.</param>
    /// <param name="cancellationToken">Cancels binding the invocation.</param>
    /// <returns>The argument's value operation, so its constant, <c>typeof</c> or lambda is reachable.</returns>
    public static IOperation? ArgumentFor(
        this InvocationExpressionSyntax invocation,
        SemanticModel model,
        string parameter,
        CancellationToken cancellationToken)
    {
        if (model.GetOperation(invocation, cancellationToken) is not IInvocationOperation operation)
        {
            return null;
        }

        foreach (var argument in operation.Arguments)
        {
            if (argument.Parameter?.Name == parameter)
            {
                return WrittenValue(argument);
            }
        }

        return null;
    }

    /// <summary>
    /// Finds the method <paramref name="invocation"/> calls when it is declared in
    /// <paramref name="containingType"/>, matching a constructed generic type by its definition;
    /// null when the method is declared elsewhere or the call does not bind.
    /// </summary>
    /// <param name="invocation">The invocation to read.</param>
    /// <param name="model">The semantic model of the invocation's syntax tree.</param>
    /// <param name="containingType">The containing type's metadata name, such as <c>Ns.Type`1</c>.</param>
    /// <param name="cancellationToken">Cancels binding the invocation.</param>
    /// <returns>The called method, an extension method as its declaration rather than its reduced form.</returns>
    public static IMethodSymbol? ResolveMethodIn(
        this InvocationExpressionSyntax invocation,
        SemanticModel model,
        string containingType,
        CancellationToken cancellationToken)
    {
        if (model.GetSymbolInfo(invocation, cancellationToken).Symbol is not IMethodSymbol bound)
        {
            return null;
        }

        var method = Declaration(bound);

        return IsIn(method, containingType) ? method : null;
    }

    // An extension method called on its receiver binds to a reduced copy without the this parameter.
    private static IMethodSymbol Declaration(IMethodSymbol method)
    {
        return method.ReducedFrom ?? method;
    }

    private static bool IsIn(IMethodSymbol method, string containingType)
    {
        return FullMetadataName(method.ContainingType.OriginalDefinition) == containingType;
    }

    private static string FullMetadataName(INamedTypeSymbol type)
    {
        if (type.ContainingType is { } outer)
        {
            return FullMetadataName(outer) + "+" + type.MetadataName;
        }

        return type.ContainingNamespace is { IsGlobalNamespace: false } ns
            ? ns.ToDisplayString() + "." + type.MetadataName
            : type.MetadataName;
    }

    // The compiler fills an omitted optional parameter with its default; the caller wrote nothing.
    private static IOperation? WrittenValue(IArgumentOperation argument)
    {
        return argument.ArgumentKind == ArgumentKind.DefaultValue ? null : argument.Value;
    }
}
